      <dd>2023-10-01</dd>
      <dt style={{ fontWeight: 'bold' }}>License</dt>
      <dd>MIT</dd>
    </dl>
  );
}

function ProcessSteps({ steps }) {
  return (
    <ol>
      {steps.map((step, index) => (
        <li key={index} style={{ marginBottom: '8px' }}>
          <span style={{ fontWeight: 'bold' }}>{step.step}:</span> {step.description}
        </li>
      ))}
    </ol>
  );
}

function App() {
  const features = [
    { label: 'Responsive Layout', value: 'Adapts to various screen sizes' },
    { label: 'Accessibility', value: 'Keyboard and screen reader support' },
    { label: 'SEO Friendly', value: 'Optimized for search engines' },
    { label: 'Performance', value: 'Fast and efficient rendering' },
  ];

  const steps = [
    { step: 'Step 1', description: 'Initialize the application state' },
    { step: 'Step 2', description: 'Render the header and navigation' },
    { step: 'Step 3', description: 'Display main content sections' },
    { step: 'Step 4', description: 'Show quick facts and footer' },
  ];

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', margin: '0 auto', maxWidth: '800px', padding: '20px' }}>
      <Header />
      <main>
        <Section title="Introduction">
          <p>
            Welcome to our React demo page. This page is structured to showcase a comprehensive layout using React components without any external assets.
          </p>
        </Section>
        <Section title="Core Features">
          <FeatureList features={features} />
        </Section>
        <Section title="Process Overview">
          <ProcessSteps steps={steps} />
        </Section>
        <Section title="Detailed Explanation">
          <article style={{ marginBottom: '20px' }}>
            <h3>Subsection: Layout Details</h3>
            <p>
              The page is divided into several sections. Each section uses headings, paragraphs, lists, and definition lists to organize content clearly.
            </p>
          </article>
          <article>
            <h3>Subsection: Technical Specifications</h3>
            <p>
              The implementation is done using functional React components. Styles are kept inline to ensure that the page remains standalone and self-contained.
            </p>
            <ul style={{ paddingLeft: '20px' }}>
              <li>Use of semantic HTML elements</li>
              <li>Clear division of content areas</li>
              <li>Consistent styling without external dependencies</li>
            </ul>
          </article>
        </Section>
      </main>
      <aside style={{ background: '#f9f9f9', padding: '15px', marginTop: '20px' }}>
        <h2>Quick Facts</h2>
        <QuickFacts />
      </aside>
      <footer style={{ borderTop: '2px solid #ccc', marginTop: '30px', paddingTop: '10px' }}>
        <Section title="Footer">
          <p>
            &copy; 2023 My React Layout. All rights reserved. This is a demonstration of a complete, self-contained React page for static content rendering.
          </p>
        </Section>
      </footer>
    </div>
  );
}

export default App;
